import{c as t,Q as o,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"以 caveman 為基礎開發新 SKILL 之可行性報告","description":"","frontmatter":{"date":"2026-07-11T00:00:00.000Z","status":"draft-for-review","non-goals":"不建 SKILL 檔（本檔為提案，非落地產物）","topic":"caveman-based-output-compression-skill","type":"feasibility-report"},"headers":[],"relativePath":"research/reports/2026-07-11-caveman-skill-feasibility.md","filePath":"research/reports/2026-07-11-caveman-skill-feasibility.md","lastUpdated":1785909234000}'),s={name:"research/reports/2026-07-11-caveman-skill-feasibility.md"};function d(n,e,c,l,i,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="以-caveman-為基礎開發新-skill-之可行性報告" tabindex="-1">以 caveman 為基礎開發新 SKILL 之可行性報告 <a class="header-anchor" href="#以-caveman-為基礎開發新-skill-之可行性報告" aria-label="Permalink to &quot;以 caveman 為基礎開發新 SKILL 之可行性報告&quot;">​</a></h1><p><strong>一句話結論</strong>：條件可行——caveman 的壓縮語法可借用，但其零保真驗證、零模型檔位適配兩大缺陷須用本 workspace 既有的「白名單不變式 + 檔位校準表 + 機械失真閘」補強後才能落地，不可原樣移植。</p><hr><h2 id="_1-caveman-具體壓縮機制-原文引證" tabindex="-1">1. Caveman 具體壓縮機制（原文引證） <a class="header-anchor" href="#_1-caveman-具體壓縮機制-原文引證" aria-label="Permalink to &quot;1. Caveman 具體壓縮機制（原文引證）&quot;">​</a></h2><p>來源：<code>github.com/juliusbrussee/caveman</code>（README、<code>skills/caveman/SKILL.md</code>、<code>skills/caveman-compress/SKILL.md</code>、<code>CLAUDE.md</code>、<code>benchmarks/run.py</code>，均 2026-07-11 WebFetch 讀取）。</p><h3 id="_1-1-壓縮手法-規則式風格改寫-非模型再訓練" tabindex="-1">1.1 壓縮手法 = 規則式風格改寫，非模型再訓練 <a class="header-anchor" href="#_1-1-壓縮手法-規則式風格改寫-非模型再訓練" aria-label="Permalink to &quot;1.1 壓縮手法 = 規則式風格改寫，非模型再訓練&quot;">​</a></h3><p><code>skills/caveman/SKILL.md</code> 原文：</p><blockquote><p>&quot;Drop: articles (a/an/the), filler (just/really/basically/actually/simply), pleasantries...Fragments OK.&quot;</p></blockquote><p>即靠<strong>system prompt 規則清單</strong>（非 few-shot、非微調）驅動：刪冠詞、刪填充詞、刪客套語、用短同義詞、允許片段句、重排資訊順序（先結果後解釋）。五個強度分級：<code>lite</code>（僅刪填充詞，保留完整句/冠詞）→ <code>full</code>（預設，刪冠詞+片段化）→ <code>ultra</code>（連連接詞都可省）→ <code>wenyan-lite/full/ultra</code>（改寫成文言文，最高達 80–90% 字元縮減）。</p><h3 id="_1-2-遞送機制-三通道-claude-md" tabindex="-1">1.2 遞送機制 = 三通道（<code>CLAUDE.md</code>） <a class="header-anchor" href="#_1-2-遞送機制-三通道-claude-md" aria-label="Permalink to &quot;1.2 遞送機制 = 三通道（`CLAUDE.md`）&quot;">​</a></h3><ol><li>SessionStart hook 注入完整規則為隱藏 system context</li><li><code>SKILL.md</code> frontmatter（支援結構化 skill 的 agent）</li><li>單一真源 <code>caveman-activate.md</code> 經 <code>caveman-init.js</code> 複製進各 agent 專屬規則檔（<code>plugins/caveman/</code> 為 CI 自動產生鏡像，禁手動編輯）</li></ol><h3 id="_1-3-已有的保真安全閥-比預期多-但仍有限" tabindex="-1">1.3 已有的保真安全閥（比預期多，但仍有限） <a class="header-anchor" href="#_1-3-已有的保真安全閥-比預期多-但仍有限" aria-label="Permalink to &quot;1.3 已有的保真安全閥（比預期多，但仍有限）&quot;">​</a></h3><p><code>CLAUDE.md</code> 原文列出<strong>自動退回正常語氣</strong>的例外清單：</p><blockquote><p>&quot;Caveman drops to normal prose for: security warnings, irreversible action confirmations, multi-step sequences where fragment ambiguity risks misread, user confused or repeating question.&quot;</p></blockquote><p><code>caveman-compress</code>（記憶檔永久壓縮指令）另有演算法式保真層：程式碼區塊、inline code、URL/連結、檔案路徑、指令、專有名詞、日期、版號、環境變數<strong>逐字保留</strong>；標題/清單階層不動；失敗時最多重試兩次並先建 <code>.original.md</code> 備份。</p><h3 id="_1-4-benchmark-方法論-三臂設計-比自報數字看起來嚴謹" tabindex="-1">1.4 Benchmark 方法論（三臂設計，比自報數字看起來嚴謹） <a class="header-anchor" href="#_1-4-benchmark-方法論-三臂設計-比自報數字看起來嚴謹" aria-label="Permalink to &quot;1.4 Benchmark 方法論（三臂設計，比自報數字看起來嚴謹）&quot;">​</a></h3><p><code>CLAUDE.md</code>：三臂比較 — baseline（無 system prompt）／terse control（僅給「回答簡潔一點」通用指令）／skill arm（完整 caveman 規則）。目的是排除「泛用簡潔指令本身就有效果」的混淆，只算 skill 相對 terse control 的<strong>淨</strong>增量。<code>benchmarks/run.py</code> 用真實 Claude API 呼叫、記 <code>response.usage.{input,output}_tokens</code>，宣稱「Never invent or round」。</p><h3 id="_1-5-兩處經原文證實的關鍵缺陷-本任務假設-非臆測-已核實" tabindex="-1">1.5 兩處經原文證實的關鍵缺陷（本任務假設，非臆測，已核實） <a class="header-anchor" href="#_1-5-兩處經原文證實的關鍵缺陷-本任務假設-非臆測-已核實" aria-label="Permalink to &quot;1.5 兩處經原文證實的關鍵缺陷（本任務假設，非臆測，已核實）&quot;">​</a></h3><p><strong>缺陷① 無保真度評分</strong> — <code>benchmarks/run.py</code> 原文邏輯只有：</p><blockquote><p><code>savings = 1 - (caveman_medians / normal_medians)</code> 只算 token 數比例，<strong>完全沒有語意正確性 / 回答品質 / 事實保留的量化指標</strong>。三臂設計解決的是「跟誰比」的混淆，沒解決「壓完還對不對」的問題。<code>caveman-compress</code> 雖有結構元素（code/URL/path）的演算法保留，但<strong>對「一般敘述句裡的關鍵事實」（數字結論、因果鏈、否定詞）沒有等價的機械保真檢查</strong>——只保結構元素，不保語意內容。</p></blockquote><p><strong>缺陷② 無模型檔位適配</strong> — <code>benchmarks/run.py</code> 預設模型 <code>claude-sonnet-4-20250514</code>，可用 <code>--model</code> override 但<strong>benchmark 從未跑過多模型比較</strong>（單次執行=單模型）；<code>AGENTS.md</code> 只是一份 <code>@./skills/*.md</code> 的 import 清單，<strong>無任何模型能力分級或跨模型壓縮強度調整字句</strong>。壓縮強度（lite/full/ultra/wenyan）是<strong>使用者手動選</strong>，不是系統依模型檔位自動決定；換言之弱模型與強模型套用同一份規則清單，缺陷假設成立。</p><hr><h2 id="_2-與本-workspace-既有制度對照" tabindex="-1">2. 與本 workspace 既有制度對照 <a class="header-anchor" href="#_2-與本-workspace-既有制度對照" aria-label="Permalink to &quot;2. 與本 workspace 既有制度對照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Caveman 元素</th><th>Workspace 對應</th><th>Diff</th></tr></thead><tbody><tr><td>刪填充詞/冠詞/客套語</td><td><code>.claude/rules/output-discipline.md</code>「填充語禁止」「禁用詞」</td><td>方向一致，workspace 已有但無分級</td></tr><tr><td>片段化/清單化</td><td><code>output-discipline.md</code>「精簡句式」</td><td>一致</td></tr><tr><td>安全語句退回正常語氣</td><td><code>.claude/rules/core.md</code>「不可逆操作永遠等確認」「P0 安全二分」</td><td><strong>workspace 紅線更硬</strong>（core.md 是強制閘門非「退回語氣」建議）；caveman 只是 prompt 層軟退回，無確定性 gate 保證真的觸發</td></tr><tr><td>CJK 壓縮（wenyan）</td><td><code>output-discipline.md</code>「Token 效率（CJK 稅對策）」允許內部英文，但<strong>對使用者最終回應維持繁中</strong>（不 silent fork 鐵律）</td><td><strong>直接衝突</strong>：wenyan 模式改寫使用者可見輸出語言/風格，違反「不 silent fork 繁中」——若引入必須限定 wenyan 只用於 internal/scratchpad，不可用於對使用者最終回應</td></tr><tr><td>6 級可調壓縮</td><td>無對應機制（<code>model-profiles.md</code> §1 有「行為指導密度」按檔位分級，但無「輸出壓縮強度」分級）</td><td><strong>真增量</strong>：可補的結構性缺口</td></tr><tr><td>記憶檔永久壓縮 <code>/caveman-compress</code></td><td><code>memory-compactor</code> agent（壓 <code>memory/MEMORY.md</code>）邏輯不同：留決策+待辦，非風格壓縮</td><td>目的不同、可互補非取代</td></tr><tr><td>三臂 benchmark 方法論</td><td>workspace <code>research/evals/</code> 有回歸 gate（<code>model-profiles.md</code> §2.1 eval 回歸 revert 線）但無「壓縮前後語意等價」評測維度</td><td><strong>真增量</strong>：可借用三臂設計思路，但須加保真軸</td></tr></tbody></table><p>（延續 <code>research/reports/2026-07-11-fable-token-efficiency.md</code> 已收錄的初評，本報告為深讀後的具體化與差異補完，不重複列數字。）</p><hr><h2 id="_3-失真風險分析" tabindex="-1">3. 失真風險分析 <a class="header-anchor" href="#_3-失真風險分析" aria-label="Permalink to &quot;3. 失真風險分析&quot;">​</a></h2><h3 id="_3-1-哪類內容壓縮後最易失真" tabindex="-1">3.1 哪類內容壓縮後最易失真 <a class="header-anchor" href="#_3-1-哪類內容壓縮後最易失真" aria-label="Permalink to &quot;3.1 哪類內容壓縮後最易失真&quot;">​</a></h3><table tabindex="0"><thead><tr><th>內容類型</th><th>失真機制</th><th>Caveman 現有防護</th><th>缺口</th></tr></thead><tbody><tr><td>數字/百分比/版號</td><td>片段化重排時易漏字或誤植鄰近數字</td><td>無（僅 code/URL/path 有演算法保留，一般敘述句數字不在保留清單）</td><td><strong>高風險缺口</strong></td></tr><tr><td>否定詞（不/非/禁止/never）</td><td>刪連接詞、片段化時否定範圍易歧義（&quot;not X unless Y&quot; 壓成片段可能丟失 unless 的例外條件）</td><td>部分：ultra 級「strips conjunctions when meaning stays clear」——「stays clear」由模型自判，非機械驗證</td><td><strong>高風險缺口，且防護是自我判斷非外部 gate</strong></td></tr><tr><td>檔案路徑/error string</td><td>逐字保留</td><td>有（<code>caveman-compress</code> 明列）</td><td>已覆蓋</td></tr><tr><td>安全紅線語句</td><td>語氣退回正常但<strong>依賴模型自己識別「這是安全警告」</strong></td><td>有 exception 清單但無確定性 hook 強制</td><td><strong>中風險</strong>：與本 workspace core.md「不可逆操作永遠等確認」的<strong>強制閘門</strong>（非建議）標準不同</td></tr><tr><td>因果鏈/多步驟推理</td><td>「先結果後解釋」重排可能丟失條件從屬關係</td><td>「multi-step sequences where fragment ambiguity risks misread」有退回清單</td><td>同上，靠模型自判</td></tr><tr><td>claim 標籤（如 workspace 慣用 <code>[claim:*]</code> 或 evidence-tier 標記）</td><td>未在 caveman 保留清單中提及此類 workspace 專屬標記</td><td>無</td><td><strong>workspace 專屬缺口，caveman 原生不知道</strong></td></tr></tbody></table><h3 id="_3-2-失真的重問成本何時吃掉節省" tabindex="-1">3.2 失真的重問成本何時吃掉節省 <a class="header-anchor" href="#_3-2-失真的重問成本何時吃掉節省" aria-label="Permalink to &quot;3.2 失真的重問成本何時吃掉節省&quot;">​</a></h3><ul><li>Caveman 自報開銷：skill 本身 +1–1.5k input token/turn（<code>README.md</code> 誠實揭露）。</li><li>若壓縮造成<strong>一次</strong>因數字/否定詞失真而觸發使用者重問澄清，重問成本 ≈ 原本完整回答的 token 量（使用者需重新描述疑問 + 模型重新展開解釋，通常比原始未壓縮回答更長，因為要先確認「你剛才是不是說反了」）。</li><li>粗估平衡點：以 README 65% 平均壓縮、294 token 均值輸出估算，一輪失真重問的額外成本（重新提問 + 完整展開解釋，估 ≥800–1200 token）即可抵銷 <strong>3–4 輪</strong>正常壓縮的淨節省。壓縮強度越高（ultra/wenyan）失真機率越高，此平衡點對高壓縮級距更不利——<strong>壓縮強度與失真風險非線性，但 caveman 無數據回答「多高的壓縮級距開始邊際失真成本超過邊際節省」</strong>，此為方法論缺口（見 Unknowns）。</li></ul><hr><h2 id="_4-改良設計草案-僅供提案-非-skill-檔" tabindex="-1">4. 改良設計草案（僅供提案，非 SKILL 檔） <a class="header-anchor" href="#_4-改良設計草案-僅供提案-非-skill-檔" aria-label="Permalink to &quot;4. 改良設計草案（僅供提案，非 SKILL 檔）&quot;">​</a></h2><blockquote><p>命名建議：<code>output-compress</code>（暫定，避免與上游 caveman 品牌混淆；若之後實際借用其 slash command 語法可協商命名）。以下為<strong>報告內草案結構</strong>，非 <code>.claude/skills/</code> 實體檔案。</p></blockquote><h3 id="_4-1-保重點不變式白名單-永不壓縮" tabindex="-1">4.1 保重點不變式白名單（永不壓縮） <a class="header-anchor" href="#_4-1-保重點不變式白名單-永不壓縮" aria-label="Permalink to &quot;4.1 保重點不變式白名單（永不壓縮）&quot;">​</a></h3><p>繼承 <code>caveman-compress</code> 既有清單（code block／inline code／URL／file path／command／proper noun／date／version／env var）並<strong>擴充 workspace 專屬項</strong>：</p><ol><li>檔案路徑、error string、指令輸出逐字（同 caveman）</li><li><strong>所有數字</strong>（百分比、金額、版號、行號、日期）——不只結構元素，敘述句中的數字也鎖定</li><li><strong>否定詞與其作用域</strong>（不/非/禁止/never/unless/except）——片段化時該子句整句保留，不允許連接詞省略</li><li><strong>[claim:*] / evidence-tier / [KU|UK|UU] 等 workspace 既有標籤系統</strong>（<code>research/reports/</code> 慣例）</li><li>安全紅線語句（<code>core.md</code>「不可逆操作」「P0」相關措辭）——不只語氣退回，整段禁止壓縮</li><li><code>Done-when</code> / <code>Return {}</code> / 任務契約關鍵欄位（<code>subagent-strategy.md</code> Handoff Contract 格式）</li></ol><h3 id="_4-2-模型檔位適配壓縮強度矩陣" tabindex="-1">4.2 模型檔位適配壓縮強度矩陣 <a class="header-anchor" href="#_4-2-模型檔位適配壓縮強度矩陣" aria-label="Permalink to &quot;4.2 模型檔位適配壓縮強度矩陣&quot;">​</a></h3><p>對應 <code>.claude/refs/model-profiles.md</code> §1 檔位詞（cost/quality/ceiling/frontier），<strong>核心原理引用 core.md「雙軸伸縮」鐵律</strong>：行為指導量與能力成反比——弱模型需要更多冗餘（顯式重複、結構化格式）才能不失真，強模型可承受更高壓縮。</p><table tabindex="0"><thead><tr><th>檔位</th><th>建議壓縮上限</th><th>理由</th></tr></thead><tbody><tr><td>cost</td><td><code>lite</code>（僅刪填充詞，保留完整句/冠詞）</td><td>弱模型對片段化語意重建能力弱，<code>model-profiles.md</code> §1 已標「cost 檔位行為指導密度=高（步驟級指示）」——壓縮與此矛盾，故上限最低</td></tr><tr><td>quality</td><td><code>full</code>（預設，刪冠詞+片段化）</td><td>對齊「行為指導密度=中」，caveman 預設級距本就以中階模型測試（<code>claude-sonnet-4-20250514</code>）校準，符合</td></tr><tr><td>ceiling</td><td><code>ultra</code>（連接詞可省）</td><td>「行為指導密度=最低（目標級）」，強模型語意重建能力足以補回省略的邏輯連接</td></tr><tr><td>frontier</td><td><code>ultra</code>，<strong>但 wenyan 系列預設禁用</strong></td><td>wenyan 改變輸出語言風格，與「對使用者最終回應維持繁中」鐵律衝突（見 §2），若使用者顯式要求文言則需另立例外，非自動套用</td></tr></tbody></table><p><strong>非 Claude 模型</strong>：比照 <code>model-profiles.md</code> §6「非 Claude 模型接入程序」，初始一律鎖 <code>lite</code>，跑 5–10 代表任務校準後才可調高，不可沿用 Claude 校準值。</p><h3 id="_4-3-失真閘-機械驗證-非模型自評" tabindex="-1">4.3 失真閘（機械驗證，非模型自評） <a class="header-anchor" href="#_4-3-失真閘-機械驗證-非模型自評" aria-label="Permalink to &quot;4.3 失真閘（機械驗證，非模型自評）&quot;">​</a></h3><p>呼應 core.md「判斷 vs 決定」公理——是否失真的<strong>偵測</strong>用確定性程序，不靠模型自評「meaning stays clear」（caveman ultra 級原句的自我判斷正是本設計要避免的模式）：</p><ol><li><strong>Key-fact extraction diff</strong>：壓縮前後分別跑一次結構化抽取（數字、檔案路徑、否定子句、專有名詞）成 JSON，diff 兩份 JSON——不等於 → 壓縮失敗，自動退回上一級重試（借用 <code>caveman-compress</code> 既有「失敗重試兩次」機制，但<strong>判準從演算法保留清單擴大到語意抽取 diff</strong>）。</li><li><strong>確定性 checklist（非 LLM judge）</strong>：白名單第 2–6 類（數字/否定詞/標籤/安全語句/契約欄位）用 regex 抓取兩版本出現次數與內容比對，不用 LLM 二次判斷是否「意思一樣」（避免 judge 噪音，呼應 <code>model-profiles.md</code> §5 O15 教訓）。</li><li><strong>三臂 eval 借用 + 加保真軸</strong>：沿用 caveman <code>baseline / terse-control / skill-arm</code> 三臂設計，但每臂新增第四維度分數——「保真度」（用 1 的 JSON diff 結果算命中率），不能只看 token 節省率；落地前須在 workspace <code>research/evals/</code> 建對應 fixture。</li><li><strong>壓縮強度與失真率的邊際曲線</strong>：落地前需实测（非本報告臆測）不同檔位在不同壓縮級距下的失真率，找出 §3.2 所述「邊際失真成本超過邊際節省」的實際轉折點，作為 4.2 矩陣的最終校準依據（目前矩陣是依 core.md 雙軸伸縮公理<strong>推導</strong>，非实测，須標記為草案）。</li></ol><h3 id="_4-4-適用-禁用場景-do-do-not" tabindex="-1">4.4 適用/禁用場景（Do / Do NOT） <a class="header-anchor" href="#_4-4-適用-禁用場景-do-do-not" aria-label="Permalink to &quot;4.4 適用/禁用場景（Do / Do NOT）&quot;">​</a></h3><p><strong>適用</strong>：</p><ul><li>內部 scratchpad／sub-agent 中間輸出／機械化報告的正文敘述段落</li><li>對已熟悉領域使用者的例行技術問答（bug fix 說明、log 解讀）</li><li>記憶檔（<code>memory/MEMORY.md</code> 類）非決策段落的壓縮（仍需與既有 <code>memory-compactor</code> 分工，不重疊）</li></ul><p><strong>禁用（Do NOT use for）</strong>：</p><ul><li>對使用者的最終回應中<strong>改變語言</strong>（wenyan 模式）——違反 <code>output-discipline.md</code>「不 silent fork 繁中鐵律」</li><li>安全紅線語句、不可逆操作確認、P0 報告（<code>core.md</code>）——<strong>這些已有更嚴格的強制格式要求</strong>（摘要+等待確認），壓縮與此格式要求衝突，且失真代價（誤判可逆性）不可承受</li><li>正式 Handoff Contract / Done-when 條款（<code>subagent-strategy.md</code>）——契約類文字的精確性本身就是契約，壓縮即改變契約語意</li><li>稽核/审查類輸出（<code>security-reviewer</code>／<code>reviewer</code> agent 產出）——finding 必須逐字可追溯到 artifact，壓縮片段化會削弱可稽核性</li><li>弱檔位（cost 級）且任務屬「off-rails」（空間常識/無 spec 推斷，見 core.md OBSERVE）——弱模型本已需要更多顯式指導，壓縮方向相反</li></ul><hr><h2 id="_5-結論與建議路徑" tabindex="-1">5. 結論與建議路徑 <a class="header-anchor" href="#_5-結論與建議路徑" aria-label="Permalink to &quot;5. 結論與建議路徑&quot;">​</a></h2><p><strong>條件可行</strong>。理由：</p><ul><li>Caveman 提供的壓縮<strong>語法規則</strong>（刪冠詞/填充詞、片段化、分級）與 workspace <code>output-discipline.md</code> 精神一致，可作為「量化分級」的參考起點，非全新概念。</li><li>但其兩大缺陷（零保真評分、零模型檔位適配）若原樣移植，會直接違反本 workspace 兩條既有鐵律：core.md「雙軸伸縮」（壓縮強度必須隨檔位反向調整，caveman 沒有）與「判斷 vs 決定」公理（失真偵測不可靠模型自判「meaning stays clear」）。</li><li>§4 草案已示範如何用 workspace 既有機制（<code>model-profiles.md</code> 檔位表、<code>core.md</code> 白名單/閘門公理、<code>research/evals/</code> 三臂 fixture）修補此二缺陷，技術路徑清楚，非阻塞性未知。</li></ul><p><strong>建議路徑</strong>（若使用者核准）：</p><ol><li>不直接 fork caveman 原始碼/安裝其 npm 套件——改為在 workspace 內以 §4 草案為 spec，走 <code>harness-meta</code> skill 的 <code>add-skill-REFERENCE.md</code> 流程新增 SKILL（<code>/harness-meta</code> → add skill 子流程），確保與既有 28 skills 命名/觸發詞不衝突。</li><li>落地前<strong>必須</strong>先建 §4.3 三臂 + 保真軸 eval fixture 並实测 §4.2 矩陣（目前矩陣為推導草案，非验证值），依 <code>model-profiles.md</code> §2.6 Per-Model Eval Baseline 既有方法論擴充，不可未验证就写入规则。</li><li>與現有 <code>output-discipline.md</code> 分工：<code>output-discipline.md</code> 保留<strong>定性</strong>規則（無開場白/填充語禁止類，L1 零數字鐵律不變）；新 SKILL 承載<strong>可選用、分級、需顯式啟用</strong>的量化壓縮機制（類似 caveman <code>/caveman &lt;level&gt;</code>），預設不啟用，避免與 L1 auto-load 行為疊加造成雙重壓縮或衝突。</li><li>wenyan 類語言改寫模式<strong>明確排除</strong>於首版落地範圍，若未來要做需另立提案並處理與繁中鐵律的衝突。</li></ol><hr><h2 id="unknowns" tabindex="-1">Unknowns <a class="header-anchor" href="#unknowns" aria-label="Permalink to &quot;Unknowns&quot;">​</a></h2><ul><li><strong>[KU]</strong> §3.2 的「3–4 輪節省抵銷」估算為本報告基於 README 揭露數字的粗略推導，非实测；落地前須用 §4.3 的 fixture 实际测出失真率與重問成本，不可直接採信本報告的估算值作为最终参数。</li><li><strong>[KU]</strong> caveman README 引用「2026 年 3 月論文顯示限制大模型簡短作答可提升準確率約 26 個百分點」，本報告<strong>未</strong>查證該論文出處與方法論（超出本次 allowed-paths 與時間範圍），此數字目前只是二手轉述，若要在改良設計中援引須先獨立查證原始論文。</li><li><strong>[UK]</strong> workspace 是否已有人手動試過在特定 sub-agent（如 <code>memory-compactor</code> 或 <code>doc-writer</code>）套用類似壓縮風格但未正式記錄？若有，本提案的 §4 可能與既有隱性做法重複，建議落地前先問使用者。</li><li><strong>[UU]</strong> caveman 的三個 hook（SessionStart/UserPromptSubmit/Statusline）與本 workspace 既有 22 個 hooks 是否有掛載點衝突或觸發順序依賴？本報告只讀了 caveman 端架構，未交叉核對 workspace 現有 hook 清單（<code>AGENTS.md</code> 提及 22 hooks 但本次未逐一核對掛載點），若真的落地需先跑 hook 相容性檢查，此為未主動排查的盲點。</li></ul><hr><h2 id="來源-url-清單" tabindex="-1">來源 URL 清單 <a class="header-anchor" href="#來源-url-清單" aria-label="Permalink to &quot;來源 URL 清單&quot;">​</a></h2><ol><li><a href="https://github.com/juliusbrussee/caveman%EF%BC%88repo" target="_blank" rel="noreferrer">https://github.com/juliusbrussee/caveman（repo</a> 首頁 + 目錄結構）</li><li><a href="https://raw.githubusercontent.com/juliusbrussee/caveman/main/README.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/juliusbrussee/caveman/main/README.md</a></li><li><a href="https://raw.githubusercontent.com/juliusbrussee/caveman/main/skills/caveman/SKILL.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/juliusbrussee/caveman/main/skills/caveman/SKILL.md</a></li><li><a href="https://raw.githubusercontent.com/juliusbrussee/caveman/main/skills/caveman-compress/SKILL.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/juliusbrussee/caveman/main/skills/caveman-compress/SKILL.md</a></li><li><a href="https://raw.githubusercontent.com/juliusbrussee/caveman/main/CLAUDE.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/juliusbrussee/caveman/main/CLAUDE.md</a></li><li><a href="https://raw.githubusercontent.com/juliusbrussee/caveman/main/benchmarks/run.py" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/juliusbrussee/caveman/main/benchmarks/run.py</a></li><li><a href="https://raw.githubusercontent.com/juliusbrussee/caveman/main/AGENTS.md%EF%BC%88%E7%A2%BA%E8%AA%8D%E7%82%BA" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/juliusbrussee/caveman/main/AGENTS.md（確認為</a> @import 清單，無模型檔位內容）</li><li><a href="https://github.com/juliusbrussee/caveman/tree/main/benchmarks%EF%BC%88%E7%9B%AE%E9%8C%84%E7%B5%90%E6%A7%8B%E7%A2%BA%E8%AA%8D%EF%BC%89" target="_blank" rel="noreferrer">https://github.com/juliusbrussee/caveman/tree/main/benchmarks（目錄結構確認）</a></li><li><a href="https://github.com/juliusbrussee/caveman/tree/main/skills%EF%BC%88%E7%9B%AE%E9%8C%84%E7%B5%90%E6%A7%8B%E7%A2%BA%E8%AA%8D%EF%BC%89" target="_blank" rel="noreferrer">https://github.com/juliusbrussee/caveman/tree/main/skills（目錄結構確認）</a></li></ol><p><strong>workspace 內部對照來源</strong>：<code>/home/user/cc-workspace/.claude/rules/core.md</code>、<code>/home/user/cc-workspace/.claude/rules/output-discipline.md</code>、<code>/home/user/cc-workspace/.claude/rules/subagent-strategy.md</code>、<code>/home/user/cc-workspace/.claude/refs/model-profiles.md</code>、<code>/home/user/cc-workspace/research/reports/2026-07-11-fable-token-efficiency.md</code></p>',62)])])}const p=t(s,[["render",d]]);export{h as __pageData,p as default};
